-- Runs inside the rolled-back publication/regulation fixture.
reset role;
update public.admin_access set enabled=true;
insert into public.persons(id,name) values(pg_temp.pu_id(910),'Destinatário sem publicação');
insert into private.athletes(person_id,sex) values(pg_temp.pu_id(910),'male');
insert into public.roster_entries(id,registration_id,dispute_id,person_id,jersey) values(pg_temp.pu_id(911),pg_temp.pu_id(5),pg_temp.pu_id(3),pg_temp.pu_id(910),null);
set local role anon;
select pg_temp.pu_error('select public.get_achievement_draft_state(pg_temp.pu_id(3))','42501');
set local role service_role;
select pg_temp.pu_error('select public.get_achievement_draft_state(pg_temp.pu_id(3))','42501');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(99)::text,true);
select pg_temp.pu_error('select public.get_achievement_draft_state(pg_temp.pu_id(3))','PT403');
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_assert(public.get_achievement_draft_state(pg_temp.pu_id(3))->'version'='0','no invented draft');
reset role;
create function pg_temp.ad_doc() returns jsonb language sql as $$select jsonb_build_object('disputeId',pg_temp.pu_id(3),'placements',jsonb_build_array(jsonb_build_object('position',1,'registrationIds',jsonb_build_array(pg_temp.pu_id(5),pg_temp.pu_id(6)))),'honors',jsonb_build_array(jsonb_build_object('id',pg_temp.pu_id(900),'title',' MVP ','personIds',jsonb_build_array(pg_temp.pu_id(201)))))$$;
create function pg_temp.ad_command(n integer default 1,v integer default 0) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.pu_id(40000+n),'expectedVersion',v,'expectedContextFingerprint',public.get_achievement_context(pg_temp.pu_id(3))->'contextFingerprint','source',null,'draft',pg_temp.ad_doc())$$;
grant execute on function pg_temp.ad_doc(),pg_temp.ad_command(integer,integer) to authenticated;
set local role authenticated;
create temp table ad_original as select pg_temp.ad_command() value;
select pg_temp.pu_assert(public.save_achievement_draft((select value from ad_original))->'version'='1','first save');
create temp table ad_first as select public.get_achievement_draft_state(pg_temp.pu_id(3)) value;
select pg_temp.pu_assert((select value#>>'{draft,honors,0,title}'='MVP' from ad_first),'title normalized');
select pg_temp.pu_assert(public.save_achievement_draft((select value from ad_original))->'version'='1','retry returns same ACK');
select public.save_achievement_draft((select value from ad_original)) as achievement_draft_ack;
select pg_temp.pu_error('select public.save_achievement_draft(pg_temp.ad_command(2))','PT409');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set((select value from ad_original),'{source}',jsonb_build_object('kind','group','phaseId',pg_temp.pu_id(610),'groupId',pg_temp.pu_id(611))))$q$,'PT409');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{draft,placements,0,registrationIds}',jsonb_build_array(pg_temp.pu_id(606))))$q$,'PT400');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{draft,honors,0,personIds}',jsonb_build_array(pg_temp.pu_id(9999))))$q$,'PT400');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{source}',jsonb_build_object('kind','group','phaseId',pg_temp.pu_id(9999),'groupId',pg_temp.pu_id(611))))$q$,'PT400');
select pg_temp.pu_error($q$select public.save_achievement_draft(pg_temp.ad_command(2,1)||jsonb_build_object('eligibleAthletes',jsonb_build_array(pg_temp.pu_id(9999))))$q$,'PT400');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{expectedVersion}','2147483647'))$q$,'PT400');
select pg_temp.pu_error('select public.get_achievement_draft_state(pg_temp.pu_id(3),-1)','PT400');
select pg_temp.pu_error('select public.get_achievement_draft_version(pg_temp.pu_id(3),0)','PT400');
select pg_temp.pu_assert(public.get_achievement_draft_version(pg_temp.pu_id(3),100) is null,'unknown version has no synthetic history');
reset role;
create temp table ad_recent as select saved_at from public.championships where id=pg_temp.pu_id(1);
update public.persons set name='Identidade corrigida',version=version+1 where id=pg_temp.pu_id(201);
set local role authenticated;
select pg_temp.pu_assert(public.get_achievement_draft_state(pg_temp.pu_id(3))->'needsReview'='true','source change signals review without replacing draft');
select pg_temp.pu_error($q$select public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{expectedContextFingerprint}',(select value->'contextFingerprint' from ad_first)))$q$,'PT409');
select pg_temp.pu_assert(public.save_achievement_draft((select value from ad_original))->'version'='1','known old ACK survives changed source');
select pg_temp.pu_assert(public.get_achievement_draft_version(pg_temp.pu_id(3),1)#>>'{contextSnapshot,eligibleAthletes,0,version}' is not null,'source snapshot retained');
select public.get_achievement_draft_version(pg_temp.pu_id(3),1) as achievement_draft_version;
reset role;
select pg_temp.pu_assert((select c.saved_at=r.saved_at from public.championships c cross join ad_recent r where c.id=pg_temp.pu_id(1)),'failed saves/replay/reads do not touch Recentes');
-- Inject a failure after immutable history insertion; no partial head/receipt/links survive.
create function pg_temp.ad_fail() returns trigger language plpgsql as $$begin raise exception 'fixture draft failure';end$$;
create trigger achievement_fixture_failure before update on private.achievement_draft_heads for each row execute function pg_temp.ad_fail();
set local role authenticated;
select pg_temp.pu_error('select public.save_achievement_draft(pg_temp.ad_command(2,1))','P0001');
reset role;
select pg_temp.pu_assert((select count(*)=1 from private.achievement_draft_versions),'failed save rolls back version');
select pg_temp.pu_assert((select count(*)=1 from private.achievement_draft_commands),'failed save rolls back receipt');
select pg_temp.pu_assert((select count(*)=2 from private.achievement_draft_registrations) and (select count(*)=1 from private.achievement_draft_people),'failed save rolls back anchors');
select pg_temp.pu_assert((select c.saved_at=r.saved_at from public.championships c cross join ad_recent r where c.id=pg_temp.pu_id(1)),'failed transaction preserves Recentes');
drop trigger achievement_fixture_failure on private.achievement_draft_heads;
-- Ending historical membership does not remove recipient eligibility.
update public.roster_entries set ended_at=clock_timestamp(),version=version+1 where id=pg_temp.pu_id(101);
update private.athletes set sex='female' where person_id=pg_temp.pu_id(201);
set local role authenticated;
select pg_temp.pu_assert(public.save_achievement_draft(jsonb_set(pg_temp.ad_command(2,1),'{draft,honors,0,personIds}',jsonb_build_array(pg_temp.pu_id(201),pg_temp.pu_id(910))))->'version'='2','historical recipient and athlete without publication retained');
do $$begin for n in 3..23 loop perform public.save_achievement_draft(pg_temp.ad_command(n,n-1));end loop;end$$;
select pg_temp.pu_assert(public.get_achievement_draft_state(pg_temp.pu_id(3))->'hasMore'='true','history bounded at20');
select public.get_achievement_draft_state(pg_temp.pu_id(3),20) as achievement_draft_state;
-- Optional selected suggestion source stays private; empty draft remains a deliberate editable draft.
savepoint ad_optional;
select pg_temp.pu_assert(public.save_achievement_draft(jsonb_set(pg_temp.ad_command(24,23),'{source}',jsonb_build_object('kind','group','phaseId',pg_temp.pu_id(610),'groupId',pg_temp.pu_id(611))))->'version'='24','explicit source can be retained without declaring completeness');
select pg_temp.pu_assert(public.get_achievement_draft_state(pg_temp.pu_id(3))#>>'{source,kind}'='group','selected source retained');
select pg_temp.pu_assert(public.save_achievement_draft(jsonb_set(pg_temp.ad_command(25,24),'{draft}',jsonb_build_object('disputeId',pg_temp.pu_id(3),'placements','[]'::jsonb,'honors','[]'::jsonb)))->'version'='25','explicitly empty private draft accepted');
rollback to savepoint ad_optional;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(99)::text,true);
select pg_temp.pu_error('select public.save_achievement_draft((select value from ad_original))','PT403');
reset role;
update public.admin_access set user_id=pg_temp.pu_id(97);
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(97)::text,true);
select pg_temp.pu_error('select public.save_achievement_draft((select value from ad_original))','PT403');
reset role;
select pg_temp.pu_error('update private.achievement_draft_versions set saved_at=clock_timestamp()','PT409');
select pg_temp.pu_error('delete from private.achievement_draft_commands','PT409');
select pg_temp.pu_error('delete from private.achievement_draft_people','PT409');
select pg_temp.rg_restrict('delete from public.roster_entries where id=pg_temp.pu_id(911)','achievement_draft_people_roster_entry_id_fkey');
select pg_temp.pu_assert(not has_table_privilege('authenticated','private.achievement_draft_versions','SELECT') and not has_table_privilege('anon','private.achievement_draft_heads','SELECT'),'no direct access');
update public.admin_access set user_id=pg_temp.pu_id(98),enabled=false;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.pu_id(98)::text,true);
select pg_temp.pu_error('select public.save_achievement_draft((select value from ad_original))','PT403');
select pg_temp.pu_error('select public.get_achievement_draft_state(pg_temp.pu_id(3))','PT403');
select pg_temp.pu_error('select public.get_achievement_draft_version(pg_temp.pu_id(3),1)','PT403');
reset role;
